var e=JSON.parse(`[{"id":"altered-immune-system-responses","title":"Risk of Altered Immune System Responses","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/risk-of-altered-immune-system-responses/","lastUpdated":"2025-05-16","fetchStatus":"ok","hazards":["radiation","isolation","gravity"],"bodySystems":["immune"],"summary":"Spaceflight stressors such as radiation, microgravity and poor sleep can change how an astronaut's immune system behaves. This may trigger allergic reactions or wake up dormant viruses. NASA is studying these changes before longer missions.","findings":[{"text":"Earlier Earth studies indicated that shifts in immunity may increase infections.","quote":"indicated that shifts in immunity may lead to an increased incidence of infections"},{"text":"Some ISS astronauts have reported skin and allergy-type symptoms.","quote":"cold sores, rashes, atypical allergies"},{"text":"Inflight samples returned to Earth are used to track immune changes.","quote":"inflight biological samples returned to Earth to track immune system changes during spaceflight"}],"measurements":["Blood, saliva and urine samples studied as possible triggers of latent virus reactivation","Biological samples collected before and after spaceflight, and inflight samples returned to Earth"],"countermeasures":["The page describes no specific countermeasures; it describes research and sampling only"],"limitations":["What triggers reactivation of latent viruses is still being investigated","Mechanisms and long-term health effects for longer missions are not explained on the page"]},{"id":"altered-sensorimotor-vestibular-function","title":"Risk of Altered Sensorimotor and Vestibular Function","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/risk-of-altered-sensorimotor-and-vestibular-function/","lastUpdated":"2025-12-02","fetchStatus":"ok","hazards":["gravity"],"bodySystems":["brain"],"summary":"Changes in gravity, and moving between gravity environments, can cause motion sickness and spatial disorientation. This could affect tasks, vehicle control and spacewalks on Moon and Mars missions. Research is measuring post-landing disorientation and testing medicines, training and orientation aids.","findings":[{"text":"Most astronauts get motion sickness in spaceflight (no exact figure given).","quote":"The majority of astronauts experience motion sickness during spaceflight."},{"text":"Motion sickness on Earth does not predict how sick you will get in space.","quote":"does not predict how motion sick you may get during space travel"},{"text":"Researchers with the U.S. Navy are testing head movements to relieve symptoms after a flight simulator.","quote":"to test whether specific head movements could help relieve motion sickness symptoms after exiting a flight simulator"}],"measurements":["Extent of disorientation right after landing, to set a baseline for planetary landings","Motion sickness medication use via astronaut surveys","Recovery interventions tested in extended bedrest experiments"],"countermeasures":["Medicines combined with training or orientation aids","Specific head movements (being tested with the U.S. Navy)","Recovery interventions tested in bedrest studies"],"limitations":["The page gives no incidence rates","No effectiveness results are stated for the countermeasures being tested"]},{"id":"cardiovascular-adaptations","title":"Risk of Cardiovascular Adaptations","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/risk-of-cardiovascular-adaptations/","lastUpdated":"2025-05-16","fetchStatus":"ok","hazards":["gravity","distance"],"bodySystems":["heart"],"summary":"Low gravity and other spaceflight stressors can change the heart and blood vessels, raising concerns about blood clots, irregular heartbeat, cardiovascular disease and low blood pressure. The risk grows with longer missions such as a Mars trip. NASA treats this research as a priority.","findings":[{"text":"Ultrasound is used to image the heart in space.","quote":"this tool can help physicians get a better picture of the heart's structure and function"},{"text":"Exercise and diet help crews keep cardiovascular fitness.","quote":"help crews maintain cardiovascular fitness"},{"text":"Compression garments and extra fluids before landing help prevent low blood pressure.","quote":"can help to prevent low blood pressure"},{"text":"NASA calls this research a priority.","quote":"research focused on understanding and treating these risks is a priority for NASA"}],"measurements":["Ultrasound imaging of heart structure and function (no specific metrics named)"],"countermeasures":["Regular exercise and healthy diets","Lower-body compression garments and high fluid intake before landing","Enhanced training to respond to cardiovascular emergencies on future Mars missions"],"limitations":["No data on how often these conditions occur","Mechanisms and countermeasure effectiveness are not reported"]},{"id":"decompression-sickness","title":"Risk of Decompression Sickness","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/risk-of-decompression-sickness/","lastUpdated":"2025-05-16","fetchStatus":"ok","hazards":["environment"],"bodySystems":["lungs"],"summary":"Decompression sickness (the bends) can occur when astronauts go from a pressurized spacecraft to a lower-pressure spacesuit for a spacewalk. NASA uses training, oxygen pre-breathing and spacewalk-ending protocols, and is developing new suits and lower-pressure spacecraft.","findings":[{"text":"Astronauts with symptoms during a spacewalk should end it and return.","quote":"should safely but rapidly end their spacewalk"},{"text":"Pre-breathing high oxygen before spacewalks helps displace body nitrogen.","quote":"breathing carefully calibrated high levels of oxygen"},{"text":"Variable pressure suits and lower-pressure spacecraft would require trade-offs.","quote":"decisions will need to be made about risk tradeoffs"}],"measurements":["The page describes no measurement or monitoring method; it mentions Earth-based training in high- and low-pressure environments"],"countermeasures":["Earth-based pressure training","Oxygen pre-breathe before spacewalks","Variable pressure suits (in development)","Lower-pressure deep-space spacecraft"],"limitations":["No quantitative risk data","Pre-breathe levels and durations are not specified","Suit pressure vs. mobility trade-offs remain open"]},{"id":"host-microorganism-interactions","title":"Risk of Host-Microorganism Interactions","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/risk-of-host-microorganism-interactions/","lastUpdated":"2025-12-02","fetchStatus":"ok","hazards":["isolation","environment"],"bodySystems":["immune"],"summary":"Astronauts' skin and gut microbes appear to shift in space, and some microbes may become more disease-causing. Precautions exist, but some astronauts still get sick. How these changes affect disease risk is not yet known.","findings":[{"text":"Crew exposure to large groups is limited before launch.","quote":"limiting flight crew exposure to large groups in the two weeks prior to launch"},{"text":"Some microbes are more virulent in spaceflight.","quote":"Some microbes have been found to be more virulent in spaceflight"},{"text":"Surface swabs of the station and crew samples are collected.","quote":"Astronauts provide biological samples and collect swabs from the surface of the space station"},{"text":"The effect on disease risk is unknown.","quote":"how these alterations may affect the crews' chances of contracting diseases remains unknown"}],"measurements":["Changes in the microbial community on skin and in the gut","Biological samples and swabs of station surfaces"],"countermeasures":["Limiting crew exposure to large groups in the two weeks before launch","Ongoing assessment of disinfectants, anti-inflammatories and antibiotics"],"limitations":["How microbiome changes affect disease risk is unknown","Which mechanism drives the risk (microbiome, virulence, immune function) is unresolved","Interaction of changes may amplify risk"]},{"id":"hypoxia","title":"Risk of Hypoxia","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/risk-of-hypoxia/","lastUpdated":"2025-05-16","fetchStatus":"ok","hazards":["environment"],"bodySystems":["lungs","brain"],"summary":"Future deep-space cabins will be kept partially depressurized to lower astronauts' nitrogen levels, which raises the chance of mild hypoxia (low oxygen in tissues). NASA considers the risk relatively low but is still assessing it.","findings":[{"text":"Untreated mild hypoxia can cause confusion, headaches, vision problems and poor sleep.","quote":"Mild hypoxia, if untreated, can cause confusion, headaches, vision impairment, and trouble sleeping."},{"text":"Astronauts breathe pure oxygen for hours before spacewalks.","quote":"Astronauts must inhale pure oxygen over several hours prior to spacewalks to avoid decompression sickness"},{"text":"Chamber studies with volunteers help scientists learn about hypoxia.","quote":"Studying volunteers that spend hours or days in these chambers allows scientists to learn more about hypoxia"}],"measurements":["Oxygen concentration and pressure balanced in spacewalk protocols","New health monitoring protocols to track adaptation to partial depressurization (no specific metrics named)"],"countermeasures":["Constant partial cabin depressurization","Balanced oxygen-pressure protocols for spacewalks (under research)","Suits that allow raising suit pressure (under research)","Pressure-chamber studies of interventions"],"limitations":["No ground-based study tests different oxygen exposure levels in humans under spaceflight stressors","Unknown whether a mildly hypoxic, reduced-pressure environment worsens existing health issues"]},{"id":"inadequate-food-and-nutrition","title":"Risk of Inadequate Food and Nutrition","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/risk-of-inadequate-food-and-nutrition/","lastUpdated":"2025-05-16","fetchStatus":"ok","hazards":["distance","isolation"],"bodySystems":["metabolism"],"summary":"Poor food or nutrition on long missions can reduce performance and cause illness. Food must be acceptable, safe, nutritious, long-lasting and varied, which gets harder on Moon and Mars missions without regular resupply.","findings":[{"text":"More than 200 foods and beverages are available on the ISS.","quote":"More than 200 foods and beverages are available aboard the space station."},{"text":"Astronauts sample menu items and help select flight foods.","quote":"sample menu items, such as soups, meats, and vegetables"}],"measurements":["Meal acceptability, safety, nutrition, shelf life, ease of preparation and variety","Crew food preferences from pre-flight tasting"],"countermeasures":["Reducing sodium and adding new foods for variety","Enhancing diets for nutritional value","Designing a deep-space food system, tested in analogs and spaceflight"],"limitations":["No quantitative data on deficits, illness or performance effects","How shelf life will be extended for Mars-length missions is not explained"]},{"id":"eva-injury-and-performance","title":"Risk of Injury and Compromised Performance from Spacewalks","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/risk-of-injury-and-compromised-performance-from-extravehicular-activity-eva/","lastUpdated":"2025-05-16","fetchStatus":"ok","hazards":["gravity","environment","distance"],"bodySystems":["bones","heart"],"summary":"Spacewalks, real or simulated, carry risk of injury and reduced performance, expected to grow with Artemis III and later missions involving lunar surface work. NASA focuses on pressure and oxygen management, suit design and physical conditioning.","findings":[{"text":"The longest single spacewalk lasted 8 hours 56 minutes (Voss and Helms, March 12, 2001).","quote":"It lasted 8 hours and 56 minutes."},{"text":"Spacewalks are physically and mentally demanding, raising injury risk.","quote":"Spacewalks come with significant physical and mental demands, elevating injury risk."},{"text":"Deep-space spacewalks will be more frequent and longer.","quote":"During deep space missions, spacewalks will occur more frequently and last longer."}],"measurements":["Pressure and oxygen levels in both habitat and spacesuit","Pressure change from habitat to suit (decompression sickness risk)"],"countermeasures":["Prebreathe protocols to remove nitrogen","Spacesuit redesign for durability, safety and dexterity","Exercise for strength and bone maintenance"],"limitations":["No injury rates or quantified future risk","Specific lunar-surface hazards are not detailed"]},{"id":"reduced-cardiorespiratory-musculoskeletal-fitness","title":"Risk of Reduced Cardiorespiratory and Musculoskeletal Fitness","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/risk-of-reduced-cardiorespiratory-and-musculoskeletal-fitness/","lastUpdated":"2025-05-16","fetchStatus":"ok","hazards":["gravity","distance"],"bodySystems":["bones","heart","lungs"],"summary":"Microgravity weakens bones, muscles and the heart-lung system, making mission tasks harder and injuries more likely. ISS crews exercise daily to counter this, but future spacecraft will likely have less room for exercise equipment.","findings":[{"text":"Average strength and aerobic fitness loss is 10-12% of pre-mission levels.","quote":"average losses to strength and aerobic fitness are 10-12% of pre-mission levels"},{"text":"12-38% of ISS crew lose more than 20% of pre-mission fitness, depending on how it is measured.","quote":"between 12-38% of space station crew members lose more than 20% of their pre-mission fitness"},{"text":"ISS crews do 1.5 hours of exercise per day.","quote":"resistance training and aerobic exercises for 1.5 hours per day"},{"text":"Exercise is done six to seven days a week.","quote":"Six to seven days a week"},{"text":"Strength loss affects more crew than aerobic decline.","quote":"Strength loss affects a larger proportion of crew members than does the decline in aerobic fitness"}],"measurements":["Periodic fitness self-evaluations","Upper and lower body strength and endurance, flexibility, aerobic fitness, agility and coordination"],"countermeasures":["Resistance and aerobic exercise on the ISS","Exercise device designed to mimic free-weight forces","Research to optimize exercise machines and protocols for deep space"],"limitations":["Future Moon and Mars spacecraft will likely have less exercise space","Effects vary substantially between individual astronauts"]},{"id":"spaceflight-associated-neuro-ocular-syndrome-sans","title":"Risk of Spaceflight Associated Neuro-ocular Syndrome (SANS)","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/risk-of-spaceflight-associated-neuro-ocular-syndrome-sans/","lastUpdated":"2025-05-16","fetchStatus":"ok","hazards":["gravity","distance"],"bodySystems":["eyes","brain"],"summary":"SANS is a set of eye and brain changes linked to long-term weightlessness, which shifts fluids toward the head. Effects range from mild to clinically significant, and the long-term outcome is unknown. NASA treats it as a top research priority before a Mars mission.","findings":[{"text":"About 70 percent of ISS astronauts experience swelling at the back of the eye.","quote":"Approximately 70 percent of astronauts aboard the International Space Station"},{"text":"The condition was first identified in 2005 under the name VIIP Syndrome.","quote":"was identified in 2005"},{"text":"Earth analog studies use head-down tilt for weeks or months.","quote":"a six-degree head-down tilt"},{"text":"Eye exams with a fundoscope track how spaceflight affects the eye.","quote":"helps scientists track how the spaceflight environment affects the human eye"}],"measurements":["Retina examined with a fundoscope","Optic nerve swelling, retinal folds, flattening of the back of the eye and brain swelling"],"countermeasures":["Nutritional supplements that could protect the eyes (under investigation)","Mechanical interventions to reverse headward fluid shifts (under investigation)","Bed rest studies that replicate microgravity effects"],"limitations":["Long-term health outcome is unknown","Why some astronauts have only mild changes and others significant ones is not explained","No proven prevention or treatment stated"]},{"id":"spaceflight-induced-bone-changes","title":"Risk of Spaceflight-Induced Bone Changes","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/risk-of-spaceflight-induced-bone-changes/","lastUpdated":"2025-05-16","fetchStatus":"ok","hazards":["gravity"],"bodySystems":["bones"],"summary":"Bones in weight-bearing areas such as the spine and hips lose density in microgravity, which can leave astronauts prone to fractures and early osteoporosis. Resistive exercise, routine bone scans and medications such as bisphosphonates are the main approaches.","findings":[{"text":"Bones lose about 1% to 1.5% of density per month on average.","quote":"on average, bones lose between 1% and 1.5%"},{"text":"This rate applies during four-to-six-month missions.","quote":"during four-to-six-month missions"},{"text":"Crew height can increase by as much as 3% in space.","quote":"the height of crew members can increase as much as 3% in space"},{"text":"Bisphosphonates could help reduce some bone loss.","quote":"could help mitigate some spaceflight-induced bone loss"}],"measurements":["Routine bone scans before and after spaceflight, also used to check how well resistive exercise maintains bone"],"countermeasures":["Resistive exercise","Bisphosphonate medications"],"limitations":["More research is needed to know if the rate of bone loss persists on lengthy missions","More research is needed on how to counter or reverse these changes"]},{"id":"renal-stone-formation-evidence-report-update","title":"Evolution of Spaceflight Renal Stone Risks and Update to the NASA Human Research Program (HRP) Renal Stone Evidence Report and Integrated Concept of Operations","organization":"NASA Human Research Program","url":"https://ntrs.nasa.gov/citations/20230015722","lastUpdated":null,"fetchStatus":"ok","hazards":["gravity","distance"],"bodySystems":["renal"],"summary":"This NASA Technical Reports Server abstract (AsMA conference paper, May 2024) describes an update to the HRP Renal Stone Evidence Report using 9 years of astronaut renal stone surveillance data. The goal is to reduce the risk of in-flight kidney stone pain that could affect the mission. It is a conference abstract, not the HRP risk page itself.","findings":[{"text":"The update draws on 9 years of NASA astronaut renal stone surveillance data.","quote":"based on new information obtained from 9 years of data from NASA's astronaut renal stone surveillance program"},{"text":"Prevention strategies include astronaut selection.","quote":"There are known and emerging renal stone prevention strategies including astronaut selection"},{"text":"In-flight treatment options include drugs, lithotripsy and propulsive ultrasound.","quote":"In-flight treatment options include pharmaceuticals, use of lithotripsy and propulsive ultrasound"}],"measurements":["Astronaut renal stone surveillance program","ISS ultrasound technology demonstrations reviewed"],"countermeasures":["Prevention: astronaut selection, medications, resistive exercise, regular urine studies, ultrasound imaging","In-flight treatment: pharmaceuticals, lithotripsy, propulsive ultrasound, percutaneous drains"],"limitations":["Abstract gives no incidence rates or effect sizes","Effectiveness of each countermeasure is not stated","Full report PDF was not reviewed; the publication date (May 5, 2024) is a conference date, so lastUpdated is null"]}]`),t=JSON.parse(`[{"id":"hazard-radiation","title":"5 Hazards of Human Spaceflight - Space Radiation","organization":"NASA Human Research Program","url":"https://www.nasa.gov/hrp/hazards/","lastUpdated":"2026-06-12","fetchStatus":"ok","hazards":["radiation"],"bodySystems":["radiation"],"summary":"NASA lists space radiation as one of the five hazards of human spaceflight. It is invisible and considered one of the most hazardous aspects of spaceflight.","findings":[{"text":"NASA considers space radiation one of the most hazardous aspects of spaceflight.","quote":"considered one of the most hazardous aspects of spaceflight."}],"measurements":[],"countermeasures":[],"limitations":["The overview page gives no numbers, monitoring methods or countermeasures for radiation."]},{"id":"hazard-isolation","title":"5 Hazards of Human Spaceflight - Isolation and Confinement","organization":"NASA Human Research Program","url":"https://www.nasa.gov/hrp/hazards/","lastUpdated":"2026-06-12","fetchStatus":"ok","hazards":["isolation"],"bodySystems":["brain"],"summary":"Small groups confined in tight spaces for months or years may show behavioral responses. NASA says crews need careful selection, training and support.","findings":[{"text":"Crews must be carefully chosen, trained and supported for isolation and confinement.","quote":"Crews must be carefully chosen, trained, and supported"}],"measurements":["Behavioral responses in isolated crews are studied."],"countermeasures":["Careful crew selection, training, and support."],"limitations":["The overview page gives no numbers or unknowns for this hazard."]},{"id":"hazard-distance","title":"5 Hazards of Human Spaceflight - Distance from Earth","organization":"NASA Human Research Program","url":"https://www.nasa.gov/hrp/hazards/","lastUpdated":"2026-06-12","fetchStatus":"ok","hazards":["distance"],"bodySystems":[],"summary":"The farther astronauts travel, the harder it is to get instructions, supplies and medical care from Earth. Self-sufficiency becomes essential.","findings":[{"text":"Mars is on average 140 million miles from Earth.","quote":"Mars is, on average, 140 million miles from Earth."},{"text":"Planning and self-sufficiency are key to deep space missions.","quote":"Planning and self-sufficiency will be key to successful deep space missions."}],"measurements":[],"countermeasures":["Planning and self-sufficiency."],"limitations":["The overview page lists no specific unknowns."]},{"id":"hazard-gravity","title":"5 Hazards of Human Spaceflight - Gravity Fields","organization":"NASA Human Research Program","url":"https://www.nasa.gov/hrp/hazards/","lastUpdated":"2026-06-12","fetchStatus":"ok","hazards":["gravity"],"bodySystems":["bones"],"summary":"Bodies must adapt to changing gravity on the station, spacecraft, Moon, Mars and back on Earth. Muscles, bones, inner ear and organs all adjust.","findings":[{"text":"Mars gravity is three-eighths of Earth's, and astronauts could spend up to two years there.","quote":"three-eighths of Earth's gravitational pull for up to two years"}],"measurements":["Adjustment of muscles, bones, inner ear, and organs."],"countermeasures":["The page points to ground analogs, labs and the ISS as test beds for strategies; no specific countermeasure is named."],"limitations":["The page notes bodies will keep adjusting to new gravitational loads; no explicit unknowns listed."]},{"id":"hazard-environment","title":"5 Hazards of Human Spaceflight - Hostile/Closed Environments","organization":"NASA Human Research Program","url":"https://www.nasa.gov/hrp/hazards/","lastUpdated":"2026-06-12","fetchStatus":"ok","hazards":["environment"],"bodySystems":["immune"],"summary":"A spacecraft is both a home and a machine, so its environment must be carefully maintained. NASA monitors microbes and immune responses.","findings":[{"text":"NASA monitors microbial communities and tracks immune responses in spacecraft environments.","quote":"monitoring microbial communities, and tracking immune responses"}],"measurements":["Microbial communities and immune responses are monitored."],"countermeasures":["Controlling temperature, pressure, lighting, and noise."],"limitations":["The overview page lists no specific unknowns."]},{"id":"risk-behavioral-conditions","title":"Risk of Behavioral Changes and Psychiatric Disorders","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/risk-of-behavioral-conditions-and-psychiatric-disorders/","lastUpdated":"2026-02-24","fetchStatus":"ok","hazards":["isolation","distance"],"bodySystems":["brain"],"summary":"Long isolation and confinement in space can raise the chance of behavioral problems such as anxiety and depression. Long communication delays on a Mars trip add new challenges.","findings":[{"text":"Prolonged isolation and confinement can increase risk of behavioral issues.","quote":"prolonged isolation and confinement that astronauts face in space can increase risks of behavioral issues"},{"text":"Communication delays on a multi-year Mars trip will create new challenges.","quote":"extended communication delays with a multi-year trip to Mars will create new challenges"},{"text":"Windows can reduce monotony and boost mental health.","quote":"A spacecraft's windows can boost the mental health of astronauts because they reduce monotony"}],"measurements":["The page does not describe measurement methods; Earth-based isolation volunteers are studied over multiple months."],"countermeasures":["Self-care such as keeping a regular journal","Growing fresh vegetables","Regular virtual contact with family and medical professionals","Spacecraft windows","Maximizing privacy"],"limitations":["No quantitative data or effectiveness data for countermeasures.","How to support crew psychological health during long communication delays is still open."]},{"id":"risk-inadequate-teamwork","title":"Risk of Inadequate Teamwork","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/risk-of-inadequate-teamwork/","lastUpdated":"2025-12-02","fetchStatus":"ok","hazards":["isolation","distance"],"bodySystems":["brain"],"summary":"Teamwork is a priority risk for deep space missions such as Mars. Communication delays, isolation and resource limits make team dynamics harder.","findings":[{"text":"Team dynamics and cohesion are vital to mission success.","quote":"Team dynamics and cohesion is vital to mission success."},{"text":"Risks include communication delays, isolation and resource constraints.","quote":"Examples include communication delays, increased isolation, and numerous resource constraints"},{"text":"Earth-based simulations do not fully replicate spaceflight.","quote":"Though these simulations do not completely replicate the spaceflight experience"}],"measurements":["The page does not state what is measured or how."],"countermeasures":["Pre-mission team-building training","In-mission medical support","Earth-based analog simulations"],"limitations":["The page gives no quantitative data.","Analog simulations do not completely replicate spaceflight (e.g. crews are not weightless)."]},{"id":"risk-inadequate-sleep","title":"Risk from Inadequate Sleep and Irregular Schedules","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/risk-from-inadequate-sleep-and-irregular-schedules/","lastUpdated":"2025-05-16","fetchStatus":"ok","hazards":["environment","isolation"],"bodySystems":["brain"],"summary":"Astronauts face sleep loss, irregular light-dark cycles and heavy workloads. These can cause short- and long-term health effects that affect mission success.","findings":[{"text":"The ISS has 16 sunrises and sunsets per day, which can disrupt the sleep-wake cycle.","quote":"16 sunrises and sunsets per day"},{"text":"LEDs that simulate Earth's light-dark cycle are used to help astronauts sleep better.","quote":"simulate Earth's light-dark cycle to help astronauts sleep better"}],"measurements":["The page does not state what is measured or how."],"countermeasures":["LEDs that simulate Earth's light-dark cycle","Designated relaxation and self-care time","Research on light and caffeine effects on body clocks"],"limitations":["No results reported from the light and caffeine research.","No sleep duration, quality or performance data given."]},{"id":"risk-inadequate-systems-operations-support","title":"Risk of Inadequate Systems Operations Support","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/risk-of-inadequate-systems-operations-support/","lastUpdated":"2025-05-16","fetchStatus":"ok","hazards":["distance"],"bodySystems":["brain"],"summary":"On the ISS crews rely on real-time help from Mission Control when problems occur. On longer, more distant missions they must diagnose and repair systems on their own.","findings":[{"text":"NASA astronauts train on average 300 hours in simulators before launch.","quote":"NASA astronauts train, on average, 300 hours in simulators before launch"},{"text":"Crews still rely on real-time assistance when problems arise.","quote":"crews still rely on real-time assistance when problems arise."}],"measurements":["The page does not state what is measured or how."],"countermeasures":["Mission Control training on ISS systems","Pre-mission emergency training","User-friendly system design","Work with industry partners"],"limitations":["No data on how well crews perform without real-time support.","No required competency standard stated."]},{"id":"risk-injury-dynamic-loads","title":"Risk of Injury from Dynamic Loads","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/risk-of-injury-from-dynamic-loads/","lastUpdated":"2025-05-16","fetchStatus":"ok","hazards":["gravity"],"bodySystems":["bones"],"summary":"Astronauts face higher injury risk during vehicle landing due to gravity transitions, disorientation and bone loss. NASA builds human body models to understand these effects.","findings":[{"text":"Such injuries could significantly affect crew health and mission success.","quote":"Such injuries could significantly affect crew health and mission success."},{"text":"Crews on the Moon and Mars must self-egress and function autonomously shortly after landing.","quote":"crews will need to self-egress and function autonomously shortly after landing"}],"measurements":["Human body models characterize how the body is affected in spaceflight environments."],"countermeasures":["Vehicle design standards (seats, restraints)","Improved spacesuit design","Research on crew readiness at landing"],"limitations":["No quantitative injury thresholds or incidence rates.","Magnitude of bone and muscle weakening not given."]},{"id":"risk-radiation-induced-cancers","title":"Risk of Radiation-Induced Cancers","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/risk-of-radiation-induced-cancers/","lastUpdated":"2025-05-16","fetchStatus":"ok","hazards":["radiation"],"bodySystems":["radiation","heart","eyes","brain"],"summary":"Astronauts are exposed to more radiation in space than on Earth, raising cancer risk and possibly other degenerative conditions. NASA studies prevention, health surveillance and personalized risk assessment.","findings":[{"text":"Astronauts are exposed to higher radiation levels in space than on Earth.","quote":"Astronauts are exposed to higher levels of radiation in space than on Earth"},{"text":"Instruments aboard the ISS measure radiation exposure.","quote":"various instruments that measure radiation exposure are in place aboard the International Space Station"},{"text":"Moon and Mars missions extend beyond Earth's protective bubble.","quote":"missions to the Moon and Mars will extend beyond this protective bubble"},{"text":"Personal cancer risk assessments aim to use radiation dose and genetic factors.","quote":"based on radiation dose and genetic factors"}],"measurements":["Instruments on the ISS measure radiation exposure","Heavy-ion beams at the NASA Space Radiation Laboratory study effects on cells and tissue"],"countermeasures":["Radiation shielding for Artemis and the lunar Gateway","Health surveillance best practices","Medicines to counter radiation effects"],"limitations":["No quantitative risk estimates or dose thresholds given.","Shielding needs for Mars and beyond are still being considered."]},{"id":"ongoing-hrp-research","title":"Ongoing HRP Research","organization":"NASA Human Research Program","url":"https://www.nasa.gov/hrp/ongoing-hrp-research/","lastUpdated":"2026-08-18","fetchStatus":"ok","hazards":["radiation","isolation","distance","gravity","environment"],"bodySystems":["brain","immune"],"summary":"This page lists NASA Human Research Program studies on Artemis II, low Earth orbit and past investigations. Studies track crew well-being, immunity, and body changes in orbit.","findings":[{"text":"HRP uses research to develop methods to protect astronaut health and performance.","quote":"HRP uses research to develop methods to protect the health and performance of astronauts in space."},{"text":"ARCHeR monitored astronauts' well-being, activity and sleep patterns.","quote":"monitored astronauts' well-being, activity, and sleep patterns"}],"measurements":["Linked studies (21), all under https://www.nasa.gov/reference/ : archer, immune-biomarkers, artemis-ii-standard-measures, b-complex, brain-fluid-pressure, cipher, simulating-manual-piloting-for-moon-landings, spacecraft-occupant-protection, spinal-fluid-biomarkers, standard-measures, thigh-cuff, venous-haemostasis, zero-t2, omics-archive, tempus-pro; plus past investigations Altered Immunity, Food Acceptability, Food Physiology, Space Gardening, Spinal Health, Veggie Monitoring (nasa.gov/missions/station/ and nasa.gov/humans-in-space/ articles)."],"countermeasures":[],"limitations":["Page is an index; details are on the linked study pages."]},{"id":"study-archer","title":"ARCHeR","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/archer/","lastUpdated":"2026-03-17","fetchStatus":"ok","hazards":["isolation","radiation"],"bodySystems":["brain"],"summary":"ARCHeR tracks astronauts' well-being, activity, sleep and crew interactions during Artemis missions. It aims to show how hazards like isolation and radiation combine to affect performance.","findings":[{"text":"Data are collected with actigraphy and behavioral performance surveys before and after the mission.","quote":"Data will be collected using actigraphy and behavioral performance surveys before and after the mission."},{"text":"Actigraphy is also collected during the mission.","quote":"Actigraphy data will also be collected during the mission."}],"measurements":["Actigraphy (wearable activity monitoring)","Behavioral performance surveys before and after the mission"],"countermeasures":["Goal: develop protocols, interventions, and technologies (none named)"],"limitations":["No sample size, results or metrics given."]},{"id":"study-immune-biomarkers","title":"Immune Biomarkers","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/immune-biomarkers/","lastUpdated":"2026-03-17","fetchStatus":"ok","hazards":["environment"],"bodySystems":["immune"],"summary":"Starting with Artemis II, this study examines how spaceflight changes crew physiology including the immune system, using blood and saliva samples.","findings":[{"text":"The study aims to potentially counter spaceflight effects on the immune system.","quote":"potentially counter the effect of spaceflight on the immune system"},{"text":"Details about dormant virus reactivation in space are still being explored.","quote":"details about this phenomenon are still being explored"}],"measurements":["Blood before and after the mission","Dry saliva blotted onto paper, collected in space and on Earth","Stress hormones, viruses and cells"],"countermeasures":[],"limitations":["No sample sizes or results given.","Dormant virus reactivation is still being explored."]},{"id":"study-brain-fluid-pressure","title":"Brain Fluid Pressure","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/brain-fluid-pressure/","lastUpdated":"2025-06-04","fetchStatus":"ok","hazards":["gravity"],"bodySystems":["brain","eyes"],"summary":"This flight study examines whether pressure of fluid inside the head is linked to eye and brain changes after long spaceflight (SANS). Fluid shifts in microgravity may raise intracranial pressure.","findings":[{"text":"Visual Impairment Intracranial Pressure Syndrome was identified in 2005.","quote":"was identified in 2005"}],"measurements":["Intracranial pressure","Eye pressure and neck vein pressure","Spinal fluid, blood and urine biomarkers, measured shortly after return and compared with preflight baselines"],"countermeasures":[],"limitations":["Whether spaceflight is associated with these changes is what the study tests.","Which biomarkers and which crew are at higher risk is unknown."]},{"id":"study-cipher","title":"CIPHER","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/cipher/","lastUpdated":"2025-06-04","fetchStatus":"ok","hazards":["gravity","radiation","isolation"],"bodySystems":["eyes","bones","heart","brain"],"summary":"CIPHER is a suite of 14 studies on how spaceflight affects the eyes, bones, heart and brain. Data are collected before, during and after missions up to a year.","findings":[{"text":"The suite has 14 studies.","quote":"This suite of 14 studies is designed to provide a better understanding"},{"text":"Studies check whether bone and muscle loss changes after six months in space.","quote":"after six months in space"},{"text":"Some studies collect samples on missions up to a year.","quote":"missions lasting up to a year will provide blood and urine samples"}],"measurements":["Blood and urine (calcium, joint biomarkers, telomeres)","MRI, CT and ultrasound of the heart and arteries","3D imaging of bones","Vision tests, vestibular tests"],"countermeasures":["Resistive exercise studied for bone loss (as stated on page)"],"limitations":["Whether bone/muscle loss accelerates after six months","Whether vision changes worsen with mission length","No results reported"]},{"id":"study-standard-measures","title":"Standard Measures","organization":"NASA Human Research Program","url":"https://www.nasa.gov/reference/standard-measures/","lastUpdated":"2025-06-04","fetchStatus":"ok","hazards":["isolation","gravity","radiation","distance","environment"],"bodySystems":["brain","immune","bones"],"summary":"This flight study collects a standard set of measurements across many body systems before, during and after spaceflight to inform protocols for Moon and Mars missions.","findings":[{"text":"Standardized measurements are collected across multiple body systems and time points.","quote":"This study collects a standardized set of measurements across multiple body systems and at various time points"},{"text":"Activity and light exposure are gathered through a wrist sensor.","quote":"measurements of activity and light exposure (gathered through a wrist sensor)"},{"text":"Saliva is used to measure immune function.","quote":"saliva to measure the function of the immune system"}],"measurements":["Wrist sensor for activity and light","Sleep reports","Fluid samples for diet and nutrition","Saliva for immune function","Cognition, sensorimotor and strength tests","Fecal samples for gut microbes"],"countermeasures":[],"limitations":["No sample sizes or results given; no unknowns explicitly listed."]},{"id":"csa-why-experiments-in-space","title":"Why do we conduct science experiments in space?","organization":"Canadian Space Agency","url":"https://www.asc-csa.gc.ca/eng/iss/science/why-do-we-conduct-science-experiments-in-space.asp","lastUpdated":"2025-10-28","fetchStatus":"ok","hazards":["gravity","radiation","isolation","distance"],"bodySystems":["bones","heart","brain"],"summary":"ISS research prepares for deep-space missions and also helps health on Earth, for example for balance problems, osteoporosis, cardiovascular disorders and Type 2 diabetes.","findings":[{"text":"About 200 international experiments are on the ISS at any time.","quote":"On average, there are 200 international space experiments on board the ISS at any given time."},{"text":"Six months in space gives data that would take years on Earth.","quote":"Studying the human body in space for six months gives us data that would take years to gather on Earth."}],"measurements":["Bones, heart, blood vessels and brain"],"countermeasures":["Goal is to find countermeasures and treatments; none named."],"limitations":["No specific countermeasures or quantitative data given."]}]`),n=JSON.parse(`[{"id":"radiation-career-limit","parameter":"NASA career space-radiation effective dose limit","value":600,"valueMax":null,"unit":"mSv","context":"Individual astronaut, total career, space flight radiation; universal for all ages and sexes","source":{"title":"NASA-STD-3001 Volume 1, Revision B, requirement [V1 4030] (also in OCHMO-TB-020 Rev E technical brief)","organization":"NASA OCHMO","url":"https://standards.nasa.gov/sites/default/files/standards/NASA/B/2022-01-05-NASA-STD-3001-Vol1-Rev-B-Final-Draft-Signature-010522.pdf","date":"2022-01-05"},"quote":"An individual astronaut's total career effective radiation dose due to space flight radiation exposure shall be less than 600 mSv. This limit is universal for all ages and sexes.","confidence":"verified","notes":"Rev B approved 2022-01-05; Rev C approved 2023-09-15 and NASA's Oct 2023 LSAH newsletter still cites the 600 mSv career limit. Replaced the older age/sex-based limits. Technical brief: https://www.nasa.gov/wp-content/uploads/2023/03/radiation-protection-technical-brief-ochmo.pdf"},{"id":"radiation-iss-daily-dose","parameter":"Typical ISS crew radiation dose rate","value":0.5,"valueMax":null,"unit":"mSv/day","context":"International Space Station, low Earth orbit","source":{"title":"The Lifetime Surveillance of Astronaut Health Newsletter, Oct 2023, Vol 28 Issue 2","organization":"NASA","url":"https://www.nasa.gov/wp-content/uploads/2023/10/lsah-newsletter-2023-vol28-issue2.pdf","date":"2023-10"},"quote":"astronauts on the International Space Station (ISS) receive doses in the order of 0.5 mSv/day","confidence":"verified","notes":"Order-of-magnitude figure; varies with solar cycle, altitude, shielding and location. Same newsletter compares with Earth average background of about 2.4 mSv/year. Other NASA-affiliated sources quote 0.2-0.6 mSv/day (not fetched in full). NASA-STD-3001 Vol 1 Rev B rationale also uses ~0.5 mSv/day as the surface-mission reference environment."},{"id":"radiation-mars-cruise-dose-rate","parameter":"Mars cruise galactic cosmic ray dose equivalent rate (Curiosity/MSL RAD)","value":1.8,"valueMax":null,"unit":"mSv/day","context":"Interplanetary cruise Earth to Mars inside MSL spacecraft (253-day transit), RAD instrument","source":{"title":"Data From NASA Rover's Voyage to Mars Aids Planning (JPL news; science: Zeitlin et al. 2013, Science, 'Measurements of energetic particle radiation in transit to Mars on the Mars Science Laboratory')","organization":"NASA JPL","url":"https://www.jpl.nasa.gov/news/data-from-nasa-rovers-voyage-to-mars-aids-planning/","date":"2013-05-30"},"quote":"an average of 1.8 milliSieverts of GCR per day on its journey to Mars","confidence":"verified","notes":"Zeitlin et al. report 1.84 +/- 0.30 mSv/day (value seen in a Science paper table via search snippet; not read directly because science.org returned HTTP 403). The Science abstract (via Europe PMC) states the dose equivalent for the shortest round-trip transit 'is found to be 0.66 +/- 0.12 sievert'. Measured inside a shielded spacecraft during relatively quiet solar period; only ~5% from solar particles."},{"id":"radiation-mars-surface-dose-rate","parameter":"Mars surface galactic cosmic ray dose equivalent rate (Curiosity RAD)","value":0.64,"valueMax":null,"unit":"mSv/day","context":"Mars surface, Gale crater, ~300 sols 2012-2013 (solar maximum)","source":{"title":"Mars' surface radiation environment measured with the Mars Science Laboratory's Curiosity rover (Hassler et al., Science 343(6169), 2014); value as cited in arXiv:2208.00892 'Crewed Missions to Mars'","organization":"Science (AAAS) / arXiv","url":"https://arxiv.org/pdf/2208.00892","date":"2014"},"quote":"According to Hassler et al. (2014) the average radiation dose at Gale Crater is 0.64 ± 0.12 mSv/day.","confidence":"secondary","notes":"Science paper itself was not retrievable (HTTP 403); the Europe PMC abstract confirms Hassler 2014 reports absorbed dose and dose equivalent from GCR and SEP but gives no per-day mSv. NASA Science page (https://science.nasa.gov/resource/radiation-measurements-on-mars/, 2013-12-09) gives the absorbed dose: 'a slowly varying dose rate of about 210 micrograys per day'. Quote's plus/minus sign appears as a replacement character because of PDF text extraction. Other sources round to ~0.67 mSv/day."},{"id":"radiation-moon-surface-dose-equivalent-rate","parameter":"Lunar surface dose equivalent rate (Chang'e-4 LND)","value":60,"valueMax":null,"unit":"µSv/h","context":"Lunar surface, Von Karman crater (far side), Chang'e-4 lander, LND instrument","source":{"title":"How intense and dangerous is cosmic radiation on the Moon? (DLR news on Zhang et al. 2020, Science Advances 6(39) eaaz1334)","organization":"DLR (German Aerospace Center)","url":"https://www.dlr.de/en/latest/news/2020/03/20200925_how-intense-and-dangerous-is-cosmic-radiation-on-the-moon","date":"2020-09-25"},"quote":"of around 60 microsieverts per hour","confidence":"secondary","notes":"About 1.4 mSv/day if continuous (60 x 24 = 1440 µSv/day; a Sci.News summary gives 1,369 µSv/day). DLR says the figure is the dose rate for a person in a spacesuit and ~200x higher than Earth's surface, 5-10x higher than a Frankfurt-New York flight. The primary paper's full text was not retrievable (science.org HTTP 403)."},{"id":"radiation-moon-surface-absorbed-dose-rate","parameter":"Lunar surface total absorbed dose rate in silicon (Chang'e-4 LND)","value":13.2,"valueMax":null,"unit":"µGy/h","context":"Lunar surface, Chang'e-4 lander, LND instrument; uncertainty +/- 1 µGy/h; neutral-particle component 3.1 +/- 0.5 µGy/h","source":{"title":"First measurements of the radiation dose on the lunar surface (Zhang et al., Science Advances 6(39), eaaz1334; PMID 32978156)","organization":"Science Advances (AAAS), via Europe PMC","url":"https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=DOI:10.1126/sciadv.aaz1334&resultType=core&format=json","date":"2020"},"quote":"We measured an average total absorbed dose rate in silicon of 13.2 ± 1 μGy/hour","confidence":"verified","notes":"Absorbed dose (µGy) in silicon, not dose equivalent (µSv); do not mix with the 60 µSv/h dose-equivalent figure."},{"id":"radiation-artemis-i-mission-dose","parameter":"Artemis I (uncrewed Orion) total mission dose equivalent","value":26.7,"valueMax":35.4,"unit":"mSv","context":"Orion crew module interior, Artemis I, 25.5-day lunar flight, 16 Nov - 11 Dec 2022 (range across measurement locations/instruments)","source":{"title":"Space radiation measurements during the Artemis I lunar mission (George et al., Nature 634, 48-52)","organization":"Nature (NASA authors)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11446838/","date":"2024"},"quote":"Total mission dose equivalents were 26.7–35.4 mSv","confidence":"verified","notes":"Of this, 1.80-3.94 mSv from Van Allen belt passes; GCR dose equivalent rates in Orion calculated at 0.96-1.24 mSv/day; cumulative absorbed dose up to 13.47 mGy. Uncrewed mission measurements (phantoms/detectors). NASA summary page (https://www.nasa.gov/missions/artemis/artemis-1/artemis-i-radiation-measurements-validate-orion-safety-for-astronauts/, 2024-10-09) gives no dose numbers."},{"id":"radiation-artemis-ii-expected-dose","parameter":"Artemis II crew radiation dose (expected, pre-flight statement)","value":null,"valueMax":null,"unit":"mSv","context":"Crewed Orion lunar flyby, April 2026","source":{"title":"To Protect Artemis II Astronauts, NASA Experts Keep Eyes on Sun","organization":"NASA Science","url":"https://science.nasa.gov/missions/artemis/artemis-2/to-protect-artemis-ii-astronauts-nasa-experts-keep-eyes-on-sun/","date":"2026-03-16"},"quote":"comparable to a 1-month stay on the International Space Station","confidence":"verified","notes":"No measured Artemis II mSv value found in NASA publications. Pre-flight NASA statement: expected exposure from radiation belts and GCR comparable to a 1-month ISS stay, about 5% of an astronaut's career limit (page updated 2026-03-17). Post-flight data to be released via NASA Life Sciences Data Archive (per a trade-press report; not verified at NASA). Quote is a fragment of the page's sentence."},{"id":"radiation-iss-neutron-share","parameter":"Neutron share of total ISS radiation","value":30,"valueMax":null,"unit":"%","context":"International Space Station","source":{"title":"Monitoring radiation for astronaut health","organization":"Canadian Space Agency","url":"https://www.asc-csa.gc.ca/eng/news/articles/2026/2026-02-26-monitoring-radiation-astronaut-health.asp","date":"2026-02-26"},"quote":"Neutron radiation, which contributes to about 30% of total radiation on the ISS","confidence":"verified","notes":"Approximate ('about'). Instruments per article: CANS (Canadian Active Neutron Spectrometer), 'a compact and autonomous instrument designed to measure neutron radiation exposure in space' (CSA contract to Bubble Technology Industries, $5.5 million, for continued development); bubble detectors are described as a predecessor to CANS, used on the ISS by David Saint-Jacques. The article gives no dose values. Quotes are as relayed by the fetch tool's summarizer; re-read the page before final submission."},{"id":"co2-limit-nominal","parameter":"ISS/habitat cabin CO2 partial pressure limit (1-hour average)","value":3,"valueMax":null,"unit":"mmHg","context":"Habitable volume, NASA-STD-3001 Vol 2 [V2 6004]; ISS operates at or below 3 mmHg 24-h average since the 2016 flight rule","source":{"title":"Carbon Dioxide (CO2) OCHMO-TB-004 Rev D, NASA-STD-3001 Medical Technical Brief","organization":"NASA OCHMO","url":"https://www.nasa.gov/wp-content/uploads/2023/12/ochmo-tb-004-carbon-dioxide.pdf","date":"2023-12"},"quote":"The system shall limit the average 1-hour CO2 partial pressure (ppCO2) in the habitable volume to no more than 3 mmHg.","confidence":"verified","notes":"Previously accepted range was 3.8 to 7.5 mmHg. Brief: limit keeps headache incidence below 1.4%; to keep headache risk below 1%, average 7-day CO2 should be below 2.5 mmHg. ISS levels have 'consistently remained at or below a 3.00 mmHg 24-hour average, with occasional higher brief excursions'; ISS historical range 1-9 mmHg. 0.5% CO2 = 3.8 mmHg."},{"id":"co2-symptom-headache-threshold","parameter":"CO2 level range associated with headaches","value":2.8,"valueMax":4.5,"unit":"mmHg","context":"Anecdotal associations from spaceflight missions, ISS","source":{"title":"Carbon Dioxide (CO2) OCHMO-TB-004 Rev D, NASA-STD-3001 Medical Technical Brief","organization":"NASA OCHMO","url":"https://www.nasa.gov/wp-content/uploads/2023/12/ochmo-tb-004-carbon-dioxide.pdf","date":"2023-12"},"quote":"Headaches at levels between 2.8-4.5 mmHg; worsening with increasing levels of CO2 accompanied by fatigue and malaise flushing.","confidence":"verified","notes":"Other NASA-listed symptoms: fatigue, malaise, decreased sleep and nausea above 4.5 mmHg; 5th cranial nerve dysesthesia at 4.5-5.0 mmHg; chronic cough, poor sleep, blurred vision and frontal headaches reported at 3.5 mmHg. Evidence is anecdotal."},{"id":"atmosphere-total-pressure-iss","parameter":"ISS cabin total pressure (sea-level equivalent)","value":101.3,"valueMax":null,"unit":"kPa","context":"ISS cabin, typically 14.7 psia, 21% O2","source":{"title":"Habitable Atmosphere OCHMO-TB-003 Rev A, NASA-STD-3001 Technical Brief","organization":"NASA OCHMO","url":"https://www.nasa.gov/wp-content/uploads/2023/12/ochmo-tb-003-habitable-atmosphere.pdf","date":"2023-12"},"quote":"Currently, the ISS cabin pressure is typically maintained at 14.7 psia with 21% O2, which is equivalent to sea level.","confidence":"verified","notes":"101.3 kPa = 14.7 psia = 1 atm = 760 mmHg (conversion stated in the same brief). ISS oxygen fraction is 21%."},{"id":"atmosphere-total-pressure-allowed-range","parameter":"Allowed total cabin pressure range for indefinite crew exposure","value":34.5,"valueMax":103,"unit":"kPa","context":"Any crewed vehicle/habitat, NASA-STD-3001 Vol 2 Rev D [V2 6006] (5.0 to 15.0 psia)","source":{"title":"NASA-STD-3001 Volume 2, Revision D","organization":"NASA OCHMO","url":"https://standards.nasa.gov/sites/default/files/standards/NASA/D/nasa-std-3001-vol-2-rev-d-signature.pdf","date":"2023-09-15"},"quote":"The system shall maintain the pressure to which the crew is exposed to between 34.5 kPa < pressure ≤ 103 kPa (5 psia < pressure ≤ 15.0 psia) for indefinite human exposure","confidence":"verified","notes":"Lower bound is exclusive (34.5 kPa < p). Quote taken from the standard's requirement as displayed in the technical briefs (OCHMO-TB-003/004); the Rev D PDF text confirms the 5 psia / 15 psia limits and the 30% diluent gas requirement [V2 6002]."},{"id":"atmosphere-inspired-o2-target","parameter":"Inspired oxygen partial pressure (PIO2) normoxia target range","value":145,"valueMax":155,"unit":"mmHg","context":"Crewed vehicle/habitat, indefinite exposure, NASA-STD-3001 Vol 2 Rev D Table 6.2-1 (2.80-3.00 psia)","source":{"title":"NASA-STD-3001 Volume 2, Revision D, Table 6.2-1 Inspired Oxygen Partial Pressure Exposure Ranges","organization":"NASA OCHMO","url":"https://standards.nasa.gov/sites/default/files/standards/NASA/D/nasa-std-3001-vol-2-rev-d-signature.pdf","date":"2023-09-15"},"quote":"The system shall maintain inspired oxygen partial pressure (PIO2) in accordance with Table 6.2-1--Inspired Oxygen Partial Pressure Exposure Ranges.","confidence":"verified","notes":"Table values (read from PDF text): Normoxia target PIO2 145-155 mmHg (indefinite); hyperoxia upper limit 356 mmHg (indefinite); mild hypoxia lower limit 127 mmHg (indefinite with monitoring). PIO2 is inspired (humidified) O2 pressure, not dry cabin ppO2. At sea level 14.7 psia / 21% O2 the dry-gas ppO2 is about 160 mmHg (21.3 kPa) by calculation (0.21 x 760), which is an inference, not a quoted NASA ISS value."},{"id":"atmosphere-temperature-range","parameter":"Crew health cabin temperature limits","value":18,"valueMax":27,"unit":"°C","context":"Pressurized crew cabin, NASA-STD-3001 Vol 2 Rev D [V2 6012] Crew Health Environmental Limits (excludes suited operations, ascent, entry, landing)","source":{"title":"NASA-STD-3001 Volume 2, Revision D, section 6.2.3.1","organization":"NASA OCHMO","url":"https://standards.nasa.gov/sites/default/files/standards/NASA/D/nasa-std-3001-vol-2-rev-d-signature.pdf","date":"2023-09-15"},"quote":"Figure 6.2-2 is based on ASHRAE 55 and anchored at 18°C and 75% humidity on the upper left corner and 27 °C and 25% humidity on the lower right corner.","confidence":"verified","notes":"Rationale text corner points of the Operating Limits figure (the figure itself is a graph, so limits are a temperature-humidity envelope, not independent box limits). Comfort/performance zone rationale cites studies supporting 20-25 °C and 30-60% humidity [V2 6013]. These are standard limits for design; actual ISS cabin setpoints were not fetched."},{"id":"atmosphere-relative-humidity-range","parameter":"Crew health cabin relative humidity limits","value":25,"valueMax":75,"unit":"%","context":"Pressurized crew cabin, NASA-STD-3001 Vol 2 Rev D [V2 6012] Crew Health Environmental Limits","source":{"title":"NASA-STD-3001 Volume 2, Revision D, section 6.2.3.1","organization":"NASA OCHMO","url":"https://standards.nasa.gov/sites/default/files/standards/NASA/D/nasa-std-3001-vol-2-rev-d-signature.pdf","date":"2023-09-15"},"quote":"From an engineering perspective, average humidity is to be maintained above this lower limit (25%) to ensure that the environment is not too dry to prevent static electricity buildup within the cabin","confidence":"verified","notes":"75% is the upper-left anchor at 18 °C and 25% the lower-right anchor at 27 °C of the envelope; the envelope depends on temperature. Humidity outside limits can cause dry/irritated mucous membranes or skin rashes (microbial growth at high humidity)."},{"id":"comms-delay-earth-moon","parameter":"One-way light time Earth to Moon","value":1.3,"valueMax":null,"unit":"s","context":"Average Earth-Moon distance (238,855 miles); Moon distance ranges ~357,000-407,000 km per NASA Moon Fact Sheet","source":{"title":"Voyager 1: What Is a Light-Day","organization":"NASA Science","url":"https://science.nasa.gov/mission/voyager/voyager-1/voyager-1-what-is-a-light-day/","date":"2026-11-12"},"quote":"light can traverse that distance in 1.3 seconds","confidence":"verified","notes":"Average value; min/max not stated by NASA in time units. Dividing the Moon Fact Sheet min/max distances (https://nssdc.gsfc.nasa.gov/planetary/factsheet/moonfact.html, updated 2024-01-11) by c gives roughly 1.2-1.36 s (calculation, not NASA-quoted). Round trip is about 2.6 s."},{"id":"comms-delay-earth-mars","parameter":"One-way light time Earth to Mars","value":3,"valueMax":22,"unit":"min","context":"Varies with orbital positions (closest approach to superior conjunction)","source":{"title":"Voyager 1: What Is a Light-Day","organization":"NASA Science","url":"https://science.nasa.gov/mission/voyager/voyager-1/voyager-1-what-is-a-light-day/","date":"2026-11-12"},"quote":"it can take anywhere from three minutes to 22 minutes for light to travel between the two planets","confidence":"verified","notes":"Consistent with NASA Mars Fact Sheet distances 54.6 to 401.4 million km (https://nssdc.gsfc.nasa.gov/planetary/factsheet/marsfact.html, updated 2025-05-19), which give about 3.0 to 22.3 min (calculation). An older NASA/JPL MGS FAQ gave about 4 to 21 min. Communications are also blacked out for ~2 weeks near solar conjunction."},{"id":"gravity-moon","parameter":"Moon surface gravity relative to Earth","value":0.165,"valueMax":null,"unit":"g","context":"Moon surface, 1.62 m/s2 vs Earth 9.80 m/s2","source":{"title":"Moon Fact Sheet","organization":"NASA NSSDC / Goddard Space Flight Center","url":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/moonfact.html","date":"2024-01-11"},"quote":"Surface gravity: 1.62 m/s2; ratio to Earth 0.165 (fetch-tool paraphrase of fact sheet table)","confidence":"verified","notes":"Quote is a paraphrase of table rows, not a verbatim sentence (fact sheet is a table). Roughly one-sixth of Earth gravity."},{"id":"gravity-mars","parameter":"Mars surface gravity relative to Earth","value":0.38,"valueMax":null,"unit":"g","context":"Mars mean surface gravity 3.73 m/s2","source":{"title":"Mars Fact Sheet","organization":"NASA NSSDC / Goddard Space Flight Center","url":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/marsfact.html","date":"2025-05-19"},"quote":"Surface gravity (mean): 3.73 m/s2; ratio to Earth 0.380 (fetch-tool paraphrase of fact sheet table)","confidence":"verified","notes":"Quote is a paraphrase of table rows, not a verbatim sentence. NASA Mars science FAQ also states Mars gravity is 38% of Earth's."}]`),r={equipment:[{id:`ared`,name:`Advanced Resistive Exercise Device (ARED)`,category:`resistance`,description:`The resistive (strength) exercise machine on the ISS; it uses a piston and flywheel system to provide loading.`,capabilities:[`600 lb total resistance (as stated in the exercise brief)`],source:{title:`Astronaut Exercise`,url:`https://www.nasa.gov/missions/station/iss-research/astronaut-exercise/`,date:`2024-05-20`},quote:`ARED uses a piston and flywheel system to provide loading`,capabilitySource:{title:`OCHMO-TB-031 Exercise Overview`,url:`https://www.nasa.gov/ochmo-tb-031-exercise-overview-2/`,date:`2026-04-02`},capabilityQuote:`utilizing the ARED (600lb. total resistance), then normalized to mission duration`},{id:`t2`,name:`T2 treadmill (2nd-generation ISS treadmill; COLBERT)`,category:`cardio`,description:`The ISS treadmill with vibration isolation and stabilization, used for running and aerobic exercise. NASA's brief also names the Combined Operational Load Bearing External Resistance Treadmill (COLBERT).`,capabilities:[`Speed up to 12.7 mph`,`Load up to 70% body mass`],source:{title:`OCHMO-TB-031 Exercise Overview`,url:`https://www.nasa.gov/ochmo-tb-031-exercise-overview-2/`,date:`2026-04-02`},quote:`ISS 2nd-generation treadmill with vibration isolation and stabilization (T2)`},{id:`cevis`,name:`Cycle Ergometer with Vibration Isolation and Stabilization (CEVIS)`,category:`cardio`,description:`The ISS exercise bike; it uses friction and resistance and is computer-controlled to maintain an accurate workload.`,capabilities:[`Load: peak 200 Watts`,`Speed up to 100 RPM`],source:{title:`OCHMO-TB-031 Exercise Overview`,url:`https://www.nasa.gov/ochmo-tb-031-exercise-overview-2/`,date:`2026-04-02`},quote:`ISS Cycle ergometer with vibration isolation and stabilization (CEVIS)`,descriptionSource:{title:`Astronaut Exercise`,url:`https://www.nasa.gov/missions/station/iss-research/astronaut-exercise/`,date:`2024-05-20`},descriptionQuote:`uses friction and resistance and is computer-controlled to maintain an accurate workload`}],facts:[{id:`iss-exercise-two-hours-per-day`,topic:`exercise-duration`,bodySystems:[`bones`,`heart`],text:`ISS crew members now average about two hours of exercise per day.`,value:2,unit:`hours/day`,source:{title:`Astronaut Exercise`,organization:`NASA`,url:`https://www.nasa.gov/missions/station/iss-research/astronaut-exercise/`,date:`2024-05-20`},quote:`crew members now averaging two hours of exercise per day`},{id:`bone-muscle-atrophy-without-gravity`,topic:`other`,bodySystems:[`bones`],text:`Without gravity, both bone and muscle become smaller and weaker.`,value:null,unit:null,source:{title:`Astronaut Exercise`,organization:`NASA`,url:`https://www.nasa.gov/missions/station/iss-research/astronaut-exercise/`,date:`2024-05-20`},quote:`Without Earth's gravity, both bone and muscle atrophy, or become smaller and weaker.`},{id:`exercise-10h-week-still-loss`,topic:`other`,bodySystems:[`bones`],text:`Even with up to 10 hours per week of exercise, astronauts (in the study cited by NASA) continued to lose muscle mass and bone density.`,value:10,unit:`hours/week`,source:{title:`Astronaut Exercise`,organization:`NASA`,url:`https://www.nasa.gov/missions/station/iss-research/astronaut-exercise/`,date:`2024-05-20`},quote:`Despite spending up to 10 hours per week exercising, astronauts continued to lose muscle mass and bone density.`},{id:`bone-loss-1-1-5-percent-per-month`,topic:`bone-loss`,bodySystems:[`bones`],text:`Estimated bone loss in spaceflight ranges from about 1 to 1.5 percent per month.`,value:1.5,unit:`% per month (upper estimate; range 1-1.5)`,source:{title:`OCHMO-TB-031 Exercise Overview`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/ochmo-tb-031-exercise-overview-2/`,date:`2026-04-02`},quote:`Bone loss is a known risk of spaceflight with estimates ranging from potential loss of 1-1.5 % loss per month.`},{id:`bone-bmd-standard-95-percent`,topic:`bone-loss`,bodySystems:[`bones`],text:`NASA's standard requires countermeasures to keep hip and spine bone mineral density at or above 95% of pre-mission values (90% for the femoral neck).`,value:95,unit:`% of pre-mission BMD`,source:{title:`Bone Loss OCHMO-MTB-013 Rev D (NASA-STD-3001 Medical Technical Brief)`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/wp-content/uploads/2023/12/ochmo-tb-030-bone-loss.pdf`,date:null},quote:`Countermeasures shall maintain bone mineral density of the hip and spine at or above 95% of pre-mission values and at or above 90% for the femoral neck.`},{id:`cortical-bone-load-bearing-exercise`,topic:`bone-loss`,bodySystems:[`bones`],text:`Cortical bone loss is best reduced by load-bearing exercise in flight, which substitutes for the forces of Earth gravity.`,value:null,unit:null,source:{title:`Bone Loss OCHMO-MTB-013 Rev D`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/wp-content/uploads/2023/12/ochmo-tb-030-bone-loss.pdf`,date:null},quote:`Cortical bone loss is best mitigated by providing load bearing exercise during spaceflight which substitutes for the normal forces supplied by terrestrial gravity.`},{id:`muscle-strength-80-percent`,topic:`muscle-loss`,bodySystems:[`bones`],text:`NASA's standard requires countermeasures to keep in-mission muscle strength at or above 80% of baseline.`,value:80,unit:`% of baseline`,source:{title:`OCHMO-TB-031 Exercise Overview`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/ochmo-tb-031-exercise-overview-2/`,date:`2026-04-02`},quote:`Countermeasures shall maintain in-mission skeletal muscle strength at or above 80% of baseline values.`},{id:`muscle-deconditioning-disuse`,topic:`muscle-loss`,bodySystems:[`bones`],text:`Weightlessness causes muscle deconditioning from disuse; exercise is one of the most important countermeasures against strength loss.`,value:null,unit:null,source:{title:`OCHMO-TB-031 Exercise Overview`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/ochmo-tb-031-exercise-overview-2/`,date:`2026-04-02`},quote:`Exercise is one of the most important countermeasures used to minimize loss of strength.`},{id:`cv-deconditioning-immediate`,topic:`cardiovascular`,bodySystems:[`heart`],text:`Cardiovascular deconditioning begins immediately on exposure to altered gravity and is measurable within a few days.`,value:null,unit:null,source:{title:`OCHMO-TB-031 Exercise Overview`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/ochmo-tb-031-exercise-overview-2/`,date:`2026-04-02`},quote:`acute deconditioning begins immediately upon exposure to an altered gravity environment and is measurable within a few days.`},{id:`vo2max-decline-iss`,topic:`cardiovascular`,bodySystems:[`heart`,`lungs`],text:`In long-duration ISS data, average aerobic capacity (VO2max) declined by about 7.4% (range -2.35% to -11.21%).`,value:-7.4,unit:`% VO2max`,source:{title:`OCHMO-TB-031 Exercise Overview`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/ochmo-tb-031-exercise-overview-2/`,date:`2026-04-02`},quote:`Average: -7.4% VO2max`},{id:`vo2max-minimum-eva`,topic:`cardiovascular`,bodySystems:[`heart`,`lungs`],text:`For missions with microgravity EVAs, crew must maintain an in-mission VO2max of at least 32.9 ml/(min/kg).`,value:32.9,unit:`ml/min/kg`,source:{title:`OCHMO-TB-031 Exercise Overview`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/ochmo-tb-031-exercise-overview-2/`,date:`2026-04-02`},quote:`Crewmembers shall maintain an in-mission VO2max at or above 32.9 ml/(min/kg) for missions with microgravity EVAs`},{id:`exercise-orthostatic-countermeasure`,topic:`cardiovascular`,bodySystems:[`heart`],text:`Exercise protocols are also used as a countermeasure for orthostatic intolerance (dizziness on standing after flight).`,value:null,unit:null,source:{title:`OCHMO-TB-031 Exercise Overview`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/ochmo-tb-031-exercise-overview-2/`,date:`2026-04-02`},quote:`It addresses these decrements and is also used as a countermeasure for orthostatic intolerance`},{id:`exercise-metabolic-30min`,topic:`exercise-duration`,bodySystems:[`heart`,`lungs`],text:`Metabolic (aerobic) training is approximately 30 minutes of interval or steady-state exercise.`,value:30,unit:`minutes`,source:{title:`OCHMO-TB-031 Exercise Overview`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/ochmo-tb-031-exercise-overview-2/`,date:`2026-04-02`},quote:`Approximately 30 minutes of interval or steady-state exercise`},{id:`exercise-resistive-30-60min`,topic:`exercise-duration`,bodySystems:[`bones`],text:`Resistive/strength training is 30 to 60 minutes of load-bearing training.`,value:60,unit:`minutes (upper end; range 30-60)`,source:{title:`OCHMO-TB-031 Exercise Overview`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/ochmo-tb-031-exercise-overview-2/`,date:`2026-04-02`},quote:`30-60 minutes load-bearing training`},{id:`exercise-long-duration-6-7-days`,topic:`exercise-duration`,bodySystems:[`bones`,`heart`],text:`The long-duration mission exercise table lists 6-7 days per week at 30 minutes per session.`,value:null,unit:null,source:{title:`OCHMO-TB-031 Exercise Overview`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/ochmo-tb-031-exercise-overview-2/`,date:`2026-04-02`},quote:`6-7 days/week`},{id:`sleep-average-six-hours`,topic:`sleep`,bodySystems:[`brain`],text:`Astronauts sleep an average of about six hours in space, below the 7-9 hours recommended for adults.`,value:6,unit:`hours/night`,source:{title:`Sleep Accommodations OCHMO-TB-041 Rev B`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/wp-content/uploads/2023/12/ochmo-tb-041-sleep-accommodations.pdf`,date:`2023-10-23`},quote:`These studies have shown that astronauts sleep an average of about six hours while in space, irrespective of the spaceflight mission examined or methodology used to quantify sleep.`},{id:`sleep-adult-needs-7-9`,topic:`sleep`,bodySystems:[`brain`],text:`An average adult needs 7-9 hours of sleep for optimal daytime functioning (per National Sleep Foundation and AASM, cited by NASA).`,value:9,unit:`hours (upper end; range 7-9)`,source:{title:`Sleep Accommodations OCHMO-TB-041 Rev B`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/wp-content/uploads/2023/12/ochmo-tb-041-sleep-accommodations.pdf`,date:`2023-10-23`},quote:`According to the National Sleep Foundation and American Academy of Sleep Medicine, an average adult needs 7-9 hours of sleep for optimal daytime functioning.`},{id:`sleep-iss-actigraphy-6-6-5`,topic:`sleep`,bodySystems:[`brain`],text:`Average nightly sleep on shuttle and ISS is 6-6.5 hours, rising to about 7 hours a week after landing.`,value:6.5,unit:`hours/night (upper end; range 6-6.5)`,source:{title:`Sleep Accommodations OCHMO-TB-041 Rev B`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/wp-content/uploads/2023/12/ochmo-tb-041-sleep-accommodations.pdf`,date:`2023-10-23`},quote:`Average nightly sleep duration for both shuttle and ISS is 6-6.5 hours.`},{id:`sans-prevalence-70-percent`,topic:`other`,bodySystems:[`eyes`,`brain`],text:`About 70% of crew show one or more signs of SANS (spaceflight-associated neuro-ocular syndrome) and 18% are diagnosed with clinically concerning SANS on long-duration missions.`,value:70,unit:`% of crew`,source:{title:`SANS OCHMO-MTB-001`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/wp-content/uploads/2024/02/ochmo-mtb-001-sans.pdf`,date:`2024-02-21`},quote:`70% of crew are reported to have one or more signs of SANS and 18% of crewmembers are diagnosed with clinically concerning SANS during long duration spaceflight.`},{id:`sans-impaired-sleep-factor`,topic:`sleep`,bodySystems:[`eyes`,`brain`],text:`Impaired sleep may reduce clearance of fluid waste from the brain and eye, a proposed factor in SANS.`,value:null,unit:null,source:{title:`SANS OCHMO-MTB-001`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/wp-content/uploads/2024/02/ochmo-mtb-001-sans.pdf`,date:`2024-02-21`},quote:`Impaired sleep which may reduce lymphatic/glymphatic clearance from the brain and eye.`},{id:`sans-long-duration-vision-60-percent`,topic:`other`,bodySystems:[`eyes`],text:`29% of short-duration and 60% of long-duration crew have reported vision degradation; all post-flight vision was correctable to 20/20 or better.`,value:60,unit:`% of long-duration crew`,source:{title:`SANS OCHMO-MTB-001`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/wp-content/uploads/2024/02/ochmo-mtb-001-sans.pdf`,date:`2024-02-21`},quote:`29% of short duration crewmembers and 60% of long duration crew have reported vision degradation.`},{id:`water-2-5-l-per-day`,topic:`hydration`,bodySystems:[`renal`,`metabolism`],text:`NASA's requirement is a minimum of 2.5 L of potable water per crewmember per day, for drinking and food rehydration.`,value:2.5,unit:`L/day`,source:{title:`Water - Human Consumption OCHMO-TB-027 Rev C`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/wp-content/uploads/2023/12/ochmo-tb-027-water.pdf`,date:`2023-11-29`},quote:`2.5 L/day for direct consummation and for rehydration of food`},{id:`water-eva-240-ml-per-hour`,topic:`hydration`,bodySystems:[`renal`,`metabolism`],text:`For suited EVA operations, at least 240 mL of potable water per hour must be available.`,value:240,unit:`mL/hour`,source:{title:`Water - Human Consumption OCHMO-TB-027 Rev C`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/wp-content/uploads/2023/12/ochmo-tb-027-water.pdf`,date:`2023-11-29`},quote:`The system shall provide a means for on-demand crewmember hydration while suited, including a minimum quantity of potable water of 240 mL (8.1 fl oz) per hour for EVA suited operations.`},{id:`dehydration-decrements`,topic:`hydration`,bodySystems:[`brain`,`renal`],text:`Dehydration can impair crew decision-making, concentration and physiology.`,value:null,unit:null,source:{title:`Water - Human Consumption OCHMO-TB-027 Rev C`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/wp-content/uploads/2023/12/ochmo-tb-027-water.pdf`,date:`2023-11-29`},quote:`Being well hydrated during operations is absolutely critical as dehydration can result in decrements in decision-making, concentration, and physiology of the crew.`},{id:`nutrition-inadequate-effects`,topic:`nutrition`,bodySystems:[`metabolism`,`bones`,`heart`,`immune`],text:`In space, inadequate food and nutrition has led to weight loss, bone and muscle loss, cardiovascular deconditioning and impaired immune function.`,value:null,unit:null,source:{title:`Food and Nutrition OCHMO-TB-013 Rev E`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/wp-content/uploads/2023/12/ochmo-tb-013-food-and-nutrition.pdf`,date:`2023-12-07`},quote:`In space, inadequate food and nutrition provisions and intake has led to weight loss, bone and muscle loss, cardiovascular deconditioning, and impaired immune function, among other health and performance decrements.`},{id:`nutrition-100-percent-requirements`,topic:`nutrition`,bodySystems:[`metabolism`],text:`NASA's standard requires programs to provide each crewmember 100% of calculated nutrient and energy requirements.`,value:100,unit:`% of calculated requirement`,source:{title:`Bone Loss OCHMO-MTB-013 Rev D (quoting NASA-STD-3001 V1 4020)`,organization:`NASA OCHMO`,url:`https://www.nasa.gov/wp-content/uploads/2023/12/ochmo-tb-030-bone-loss.pdf`,date:null},quote:`Programs shall provide each crewmember with 100% of their calculated nutrient and energy requirements, based on an individual's age, sex, body mass (kg), height (m), and appropriate activity factor.`}],sessionTemplates:[{id:`resistance-ared-30-60`,name:`Resistance - ARED load-bearing session (reference structure, not a prescription)`,equipment:`ared`,durationMin:60,basis:`https://www.nasa.gov/ochmo-tb-031-exercise-overview-2/ - 'Resistive/Strength: 30-60 minutes load-bearing training' (upper end shown; 30 also within range)`},{id:`cardio-t2-30`,name:`Aerobic - T2 treadmill interval or steady-state (reference structure, not a prescription)`,equipment:`t2`,durationMin:30,basis:`https://www.nasa.gov/ochmo-tb-031-exercise-overview-2/ - 'Metabolic: Approximately 30 minutes of interval or steady-state exercise'`},{id:`cardio-cevis-30`,name:`Aerobic - CEVIS cycle interval or steady-state (reference structure, not a prescription)`,equipment:`cevis`,durationMin:30,basis:`https://www.nasa.gov/ochmo-tb-031-exercise-overview-2/ - same metabolic guideline (~30 min); ~2 h/day average at https://www.nasa.gov/missions/station/iss-research/astronaut-exercise/`}]},i=[...e,...t].filter(e=>e.fetchStatus===`ok`),a=n,o=r,s={radiation:`Space radiation`,isolation:`Isolation & confinement`,distance:`Distance from Earth`,gravity:`Gravity fields`,environment:`Hostile / closed environment`};function c(e){return i.filter(t=>t.bodySystems.includes(e)&&!t.id.startsWith(`hazard-`))}export{c as a,i,o as n,s as r,a as t};